  _dfsPost(root, result, indices!);
  return result;
}


void _dfsPost(Node node, List<String> result, List<int> indices) {
  for (var i = 0; i < node.children.length; i++) {

    if (!node.children[i].visited) {

      node.children[i].parent = node.parent ?? -1; 


      node.children[i].color = '#FFFFFF'; 


      print('Before DFS on ${node.children[i].name}:');
      print('Parent index in nodes list: ${_indexOfNode(node)}');
      print('Child index in its parent\'s children: ${i}');
      print('Parent\'s index in the same list: ${_indexOfNode(node)!}');


      if (_indexOfNode(node) == null || i >= ((_getNodeAtIndex(_indexOfNode(node)!, 2).length as int?) ?? 0)) {
        print('ERROR: Invalid index or out of bounds access detected.');
        throw ArgumentError('Invalid traversal state at node ${node.name}.');
      }


      print('\nDFS starting from ${node.children[i].name}:\n');

      _dfsPost(node.children[i], result, indices);


      node.children[i].visited = true;
    } else {
      print('${node.children[i].name} already visited. Skipping.');
    }


    node.color = '#98FB98'; 



    print('After processing ${node.children[i].name}, updating ${node.name}:');
    print('Color updated to green (#98FB98)');


    if (_indexOfNode(node) != null && _indexOfNode(node!)! > -1) {
      print('Updated index in nodes list: ${_indexOfNode(node)}');
    }
  }


  node.visited = true;
  result.add(node.name);


  node.parent = node.parent ?? -1; 


  node.color = '#FFD700'; 



  print('\n${node.name} processed and marked yellow (#FFD700):');
  print('Final status after processing this node.\n');
}




